from typing import List

def split_csv_line(line: str, delimiter: str = ",") -> List[str]:
    if len(delimiter) != 1 or delimiter == '"':
        raise ValueError("Invalid delimiter")
    if not line:
        return [""]
    fields = []
    i, n = 0, len(line)
    while i < n:
        start = i
        while i < n and line[i] == ' ':
            i += 1
        if i < n and line[i] == '"':
            i += 1
            val = []
            while True:
                if i >= n: raise ValueError("Unterminated quote")
                if line[i] == '"':
                    if i + 1 < n and line[i+1] == '"':
                        val.append('"'); i += 2
                    else:
                        i += 1; break
                else:
                    val.append(line[i]); i += 1
            while i < n and line[i] != delimiter:
                if line[i] != ' ': raise ValueError("Text after quote")
                i += 1
            fields.append("".join(val))
            if i < n and line[i] == delimiter: i += 1
        else:
            i = start
            val = []
            while i < n and line[i] != delimiter:
                val.append(line[i]); i += 1
            fields.append("".join(val))
            if i < n and line[i] == delimiter: i += 1
    if n > 0 and line[-1] == delimiter: fields.append("")
    return fields
"}}}
